// <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"
//
//	stroke-linecap="round" stroke-linejoin="round">{SVG}</svg> and tints via color.
type IconDef struct {
	Name string `json:"name"`
	SVG  string `json:"svg"`
}

